class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_len = -1

        # We check for each character from 'a' to 'z'
        for c in set(s):
            # Collect all positions where the character c appears
            positions = [i for i, ch in enumerate(s) if ch == c]

            # The minimal length of substring is 1, max can be length of s
            # We'll try from longest possible lengths down to 1
            for length in range(n, 0, -1):
                count = 0
                # Slide over s and count occurrences of the substring c*length
                substring = c * length
                for i in range(n - length + 1):
                    if s[i:i+length] == substring:
                        count += 1
                    if count >= 3:
                        max_len = max(max_len, length)
                        break
                if count >= 3:
                    # No need to check smaller length for this character since longest found
                    break

        return max_len
